window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[216]={"id":"216","numero":216,"titre":"Syndrome hémorragique d'origine hématologique","objectifs":[{"id":"216-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du syndrome hémorragique d’origine hématologique","contenu":"<p>Le <span class=\"kw-def\">syndrome hémorragique d'origine hématologique</span> désigne l'ensemble des <strong>manifestations hémorragiques anormales</strong> — saignements <span class=\"kw-clinique\">spontanés</span>, <span class=\"kw-clinique\">disproportionnés</span> à un traumatisme minime, ou <span class=\"kw-clinique\">retardés</span> — traduisant une <strong>anomalie constitutionnelle ou <span class=\"kw-etio\">acquise</span> de l'hémostase</strong>. Il s'oppose au saignement dû à une simple <span class=\"kw-etio\">lésion organique localisée</span> chez un patient à hémostase normale.</p>\n      <p>L'hémostase maintient le sang fluide dans les vaisseaux ; elle comporte 3 étapes : <span class=\"kw-def\">hémostase primaire</span>, <span class=\"kw-def\">coagulation</span> (hémostase secondaire) et <span class=\"kw-def\">fibrinolyse</span>. Un déficit à <strong>n'importe lequel des 3 niveaux</strong> peut causer un syndrome <span class=\"kw-etio\">hémorragique</span>.</p>\n      <p><strong>Le type de saignement oriente d'emblée le niveau d'hémostase atteint :</strong></p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Type d'hémorragie</th><th>Spontané / provoqué</th><th>Délai</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Trouble de l'hémostase primaire</strong></td><td><span class=\"kw-clinique\">Hémorragie cutanéo-muqueuse</span> : <span class=\"kw-def\">purpura</span> ; <span class=\"kw-clinique\">ecchymoses</span> ; gingivorragies ; épistaxis</td><td>Spontané et/ou provoqué</td><td>Précoce</td></tr>\n          <tr><td><strong>Trouble de la coagulation</strong></td><td><span class=\"kw-clinique\">Hémorragie interne</span> : hématome ; hémarthrose</td><td>Provoqué par un traumatisme minime</td><td>Retardé</td></tr>\n          <tr><td><strong>Hémorragie viscérale</strong></td><td><span class=\"kw-clinique\">Méléna</span> ; <span class=\"kw-clinique\">hématémèse</span> ; <span class=\"kw-clinique\">hémoptysie</span></td><td colspan=\"2\">Évoque un trouble de l'hémostase <strong>associé à une <span class=\"kw-clinique\">lésion</span> organique</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Ne pas confondre avec le <span class=\"kw-alerte\">purpura vasculaire</span> (anomalie de la paroi vasculaire, <span class=\"kw-def\">purpura</span> infiltré et palpable) qui n'est <strong>pas</strong> d'origine hématologique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 215 — <span class=\"kw-def\">Purpura</span></em></p>","frequence":0},{"id":"216-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les différents acteurs et étapes de l’hémostase primaire, de la coagulation et de la fibrinolyse","contenu":"<p>L'hémostase est un processus qui garde le sang fluide dans les vaisseaux. Elle comporte <strong>3 étapes qui se déroulent simultanément</strong>, régulées par des inhibiteurs : elles arrêtent les hémorragies tout en évitant les thromboses.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/216/hemostase-3-etapes.png\" alt=\"Chronologie des 3 étapes de l'hémostase : hémostase primaire, coagulation puis fibrinolyse, rapportées au volume hémorragique et à l'échelle de temps\" loading=\"lazy\">\n        <figcaption>Les 3 étapes de l'hémostase rapportées au volume <span class=\"kw-etio\">hémorragique</span> : l'hémostase primaire amorce l'arrêt du saignement, la coagulation le consolide, la <span class=\"kw-ttt\">fibrinolyse</span> détruit le caillot une fois la brèche réparée. Source : fiche source EDN item 216 (Hémostase).</figcaption>\n      </figure>\n\n      <p><strong>1 · Hémostase primaire</strong> — aboutit au <span class=\"kw-def\">thrombus blanc</span> (clou plaquettaire).</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/216/hemostase-primaire-schema.png\" alt=\"Schéma de l'hémostase primaire : adhérence, activation, sécrétion et agrégation des plaquettes sur le sous-endothélium exposé\" loading=\"lazy\">\n        <figcaption>Hémostase primaire : adhérence des <span class=\"kw-bio\">plaquettes</span> au sous-endothélium (vWF, GPIb), activation avec sécrétion des granules (ADP, sérotonine, thromboxane A2), puis agrégation via les GPIIb/IIIa et le <span class=\"kw-bio\">fibrinogène</span>. Source : fiche source EDN item 216 (Hémostase).</figcaption>\n      </figure>\n      <p>Elle met en jeu <strong>4 acteurs</strong> :</p>\n      <table >\n        <thead><tr><th>Acteur</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Cellules endothéliales</span></td><td>Tapissent la paroi vasculaire ; à l'état normal, propriétés <strong>anti-plaquettaires, anti-coagulantes et anti-thrombotiques</strong> ; produisent le <span class=\"kw-bio\">NO</span> et la <span class=\"kw-bio\">prostaglandine I2 (PGI2)</span></td></tr>\n          <tr><td><span class=\"kw-def\">Plaquettes</span></td><td>Récepteur <span class=\"kw-bio\">GPIb</span> : fixe le vWF et le collagène<br>Récepteur <span class=\"kw-bio\">GPIIb/IIIa</span> : fixe le vWF et le <span class=\"kw-bio\">fibrinogène</span><br>À l'activation : libèrent ADP, vWF, <span class=\"kw-bio\">fibrinogène</span></td></tr>\n          <tr><td><span class=\"kw-def\">Facteur Willebrand (vWF)</span></td><td>Grosse protéine multimérique ; <strong>transporte et stabilise le F8</strong> ; « colle » les <span class=\"kw-bio\">plaquettes</span> au sous-endothélium (pont GPIb–collagène) ; taille régulée par <span class=\"kw-bio\">ADAMTS13</span></td></tr>\n          <tr><td><span class=\"kw-def\">Fibrinogène</span></td><td>Constitue le <strong>pont entre les GPIIb/IIIa</strong> de deux <span class=\"kw-bio\">plaquettes</span> lors de l'agrégation</td></tr>\n        </tbody>\n      </table>\n      <p>Déroulement en 3 temps : <span class=\"kw-bio\">vasoconstriction</span> → <span class=\"kw-bio\">adhérence plaquettaire</span> (le vWF établit un pont GPIb–collagène) → <span class=\"kw-bio\">activation</span> (libération d'ADP, sérotonine, thromboxane A2) → <span class=\"kw-bio\">agrégation</span> (GPIIb/IIIa + <span class=\"kw-bio\">fibrinogène</span> + Ca²⁺). Le contrôle est assuré par le <span class=\"kw-bio\">NO</span> et la <span class=\"kw-bio\">PGI2</span>, qui inhibent l'activation et l'agrégation.</p>\n\n      <p><strong>2 · Coagulation</strong> (hémostase secondaire) — aboutit au <span class=\"kw-def\">caillot de fibrine</span> (<span class=\"kw-etio\">thrombus</span> rouge).</p>\n      <figure class=\"obj-figure coag-cascade-figure\">\n        <div id=\"coag-cascade-svg\" class=\"coag-svg-animated\" role=\"img\" aria-label=\"Cascade de la coagulation animée : voies extrinsèque, intrinsèque et commune jusqu'au caillot de fibrine stable\">\n          <svg viewBox=\"0 0 720 540\" xmlns=\"http://www.w3.org/2000/svg\" preserveAspectRatio=\"xMidYMid meet\" class=\"coag-cascade-svg-inner\">\n            <defs>\n              <marker id=\"coag-arrow\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n                <path class=\"coag-arrow\" d=\"M0 0 L10 5 L0 10 z\"></path>\n              </marker>\n            </defs>\n\n            <!-- Libellés de voies (statiques) -->\n            <text class=\"coag-vlabel\" x=\"82\" y=\"11\">Intrinsèque (contact)</text>\n            <text class=\"coag-vlabel\" x=\"638\" y=\"11\">Extrinsèque (FT)</text>\n            <text class=\"coag-vlabel\" x=\"360\" y=\"199\">Voie commune</text>\n            <text class=\"coag-vlabel\" x=\"430\" y=\"418\">Fibrinoformation</text>\n\n            <!-- Flèches (tracé séquentiel via DrawSVG) -->\n            <path class=\"coag-edge\" id=\"edge-ft-fvii\" d=\"M638 56 L638 74\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-fvii-fviia\" d=\"M638 112 L638 132\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-fxii-fxi\" d=\"M82 56 L82 74\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-fxi-fix\" d=\"M82 112 L82 132\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-fix-fx\" d=\"M140 151 L300 225\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-fviia-fx\" d=\"M580 151 L420 225\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-fx-fxa\" d=\"M360 244 L360 262\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-fv-fxa\" d=\"M274 281 L302 281\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-fxa-prothrombinase\" d=\"M360 300 L360 314\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-prothrombinase-fii\" d=\"M320 350 L262 368\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-fii-fiia\" d=\"M320 386 L400 386\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-fiia-fibrine\" d=\"M465 404 L407 424\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-fibrinogene-fibrine\" d=\"M290 441 L340 441\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-fibrine-stable\" d=\"M400 458 L390 480\" marker-end=\"url(#coag-arrow)\"></path>\n            <path class=\"coag-edge\" id=\"edge-fxiii-stable\" d=\"M548 458 L474 480\" marker-end=\"url(#coag-arrow)\"></path>\n\n            <!-- Halos (AOD : cible entourée) -->\n            <rect class=\"coag-ring\" id=\"ring-fxa\" x=\"296\" y=\"256\" width=\"128\" height=\"50\" rx=\"9\"></rect>\n            <rect class=\"coag-ring\" id=\"ring-fiia\" x=\"394\" y=\"362\" width=\"142\" height=\"48\" rx=\"9\"></rect>\n\n            <!-- Croix (AOD : étape bloquée) -->\n            <g class=\"coag-cross\" id=\"cross-xa\">\n              <line x1=\"351\" y1=\"298\" x2=\"369\" y2=\"316\"></line>\n              <line x1=\"369\" y1=\"298\" x2=\"351\" y2=\"316\"></line>\n            </g>\n            <g class=\"coag-cross\" id=\"cross-iia\">\n              <line x1=\"427\" y1=\"405\" x2=\"445\" y2=\"423\"></line>\n              <line x1=\"445\" y1=\"405\" x2=\"427\" y2=\"423\"></line>\n            </g>\n\n            <!-- Nœuds : voie extrinsèque -->\n            <g class=\"coag-node\" id=\"node-ft\"><rect x=\"580\" y=\"16\" width=\"116\" height=\"40\" rx=\"7\"></rect><text x=\"638\" y=\"36\">Facteur tissulaire</text></g>\n            <g class=\"coag-node\" id=\"node-fvii\"><rect x=\"580\" y=\"74\" width=\"116\" height=\"38\" rx=\"7\"></rect><text x=\"638\" y=\"93\">FVII</text></g>\n            <g class=\"coag-node\" id=\"node-fviia\"><rect x=\"580\" y=\"132\" width=\"116\" height=\"38\" rx=\"7\"></rect><text x=\"638\" y=\"151\">FVIIa</text></g>\n\n            <!-- Nœuds : voie intrinsèque -->\n            <g class=\"coag-node\" id=\"node-fxii\"><rect x=\"24\" y=\"16\" width=\"116\" height=\"40\" rx=\"7\"></rect><text x=\"82\" y=\"36\">FXII</text></g>\n            <g class=\"coag-node\" id=\"node-fxi\"><rect x=\"24\" y=\"74\" width=\"116\" height=\"38\" rx=\"7\"></rect><text x=\"82\" y=\"93\">FXIa</text></g>\n            <g class=\"coag-node\" id=\"node-fix\"><rect x=\"24\" y=\"132\" width=\"116\" height=\"38\" rx=\"7\"></rect><text x=\"82\" y=\"151\">FIXa</text></g>\n            <g class=\"coag-node coag-cof\" id=\"node-fviii\"><rect x=\"24\" y=\"188\" width=\"116\" height=\"30\" rx=\"6\"></rect><text x=\"82\" y=\"203\">FVIIIa (cof.)</text></g>\n            <g class=\"coag-node coag-cof\" id=\"node-vwf\"><rect x=\"150\" y=\"188\" width=\"62\" height=\"30\" rx=\"6\"></rect><text x=\"181\" y=\"203\">vWF</text></g>\n\n            <!-- Nœuds : voie commune -->\n            <g class=\"coag-node\" id=\"node-fx\"><rect x=\"302\" y=\"206\" width=\"116\" height=\"38\" rx=\"7\"></rect><text x=\"360\" y=\"225\">FX</text></g>\n            <g class=\"coag-node\" id=\"node-fxa\"><rect x=\"302\" y=\"262\" width=\"116\" height=\"38\" rx=\"7\"></rect><text x=\"360\" y=\"281\">FXa</text></g>\n            <g class=\"coag-node coag-cof\" id=\"node-fv\"><rect x=\"170\" y=\"266\" width=\"104\" height=\"30\" rx=\"6\"></rect><text x=\"222\" y=\"281\">FVa (cof.)</text></g>\n            <g class=\"coag-node\" id=\"node-prothrombinase\"><rect x=\"255\" y=\"314\" width=\"210\" height=\"36\" rx=\"7\"></rect><text x=\"360\" y=\"327\">Prothrombinase</text><text class=\"coag-sub\" x=\"360\" y=\"342\">FXa · FVa · Ca²⁺ · PL</text></g>\n            <g class=\"coag-node\" id=\"node-fii\"><rect x=\"190\" y=\"368\" width=\"130\" height=\"36\" rx=\"7\"></rect><text x=\"255\" y=\"386\">Prothrombine (FII)</text></g>\n            <g class=\"coag-node\" id=\"node-fiia\"><rect x=\"400\" y=\"368\" width=\"130\" height=\"36\" rx=\"7\"></rect><text x=\"465\" y=\"386\">Thrombine (FIIa)</text></g>\n\n            <!-- Nœuds : fibrinoformation -->\n            <g class=\"coag-node\" id=\"node-fibrinogene\"><rect x=\"150\" y=\"424\" width=\"140\" height=\"34\" rx=\"7\"></rect><text x=\"220\" y=\"441\"><span class=\"kw-bio\">Fibrinogène</span></text></g>\n            <g class=\"coag-node\" id=\"node-fibrine\"><rect x=\"340\" y=\"424\" width=\"120\" height=\"34\" rx=\"7\"></rect><text x=\"400\" y=\"441\"><span class=\"kw-bio\">Fibrine</span></text></g>\n            <g class=\"coag-node coag-cof\" id=\"node-fxiii\"><rect x=\"500\" y=\"424\" width=\"96\" height=\"34\" rx=\"6\"></rect><text x=\"548\" y=\"441\">FXIIIa</text></g>\n            <g class=\"coag-node coag-final\" id=\"node-fibrine-stable\"><rect x=\"270\" y=\"480\" width=\"230\" height=\"34\" rx=\"7\"></rect><text x=\"385\" y=\"497\">Caillot de fibrine stable</text></g>\n\n            <!-- Extra révélé sur CIVD -->\n            <g class=\"coag-extra\" id=\"node-ddimeres\"><rect x=\"520\" y=\"482\" width=\"120\" height=\"30\" rx=\"6\"></rect><text x=\"580\" y=\"497\"><span class=\"kw-bio\">D-dimères</span> ↑</text></g>\n          </svg>\n        </div>\n        <div class=\"coag-controls\" role=\"group\" aria-label=\"Pathologies de la coagulation\">\n          <button type=\"button\" class=\"coag-play\" data-action=\"play\">▶ Rejouer l'animation</button>\n          <span class=\"coag-controls-sep\" aria-hidden=\"true\">·</span>\n          <button type=\"button\" class=\"coag-patho\" data-patho=\"hemophilie-a\">Hémophilie A</button>\n          <button type=\"button\" class=\"coag-patho\" data-patho=\"hemophilie-b\">Hémophilie B</button>\n          <button type=\"button\" class=\"coag-patho\" data-patho=\"willebrand\">Willebrand</button>\n          <button type=\"button\" class=\"coag-patho\" data-patho=\"avk\"><span class=\"kw-ttt\">AVK</span></button>\n          <button type=\"button\" class=\"coag-patho\" data-patho=\"aod-xa\"><span class=\"kw-ttt\">AOD</span> anti-Xa</button>\n          <button type=\"button\" class=\"coag-patho\" data-patho=\"aod-iia\"><span class=\"kw-ttt\">AOD</span> anti-IIa</button>\n          <button type=\"button\" class=\"coag-patho\" data-patho=\"civd\"><span class=\"kw-alerte\">CIVD</span></button>\n        </div>\n        <figcaption>\n          Cascade de la coagulation : la <span class=\"kw-def\">voie extrinsèque</span> (facteur tissulaire) et la <span class=\"kw-def\">voie intrinsèque</span> (contact) convergent sur la <span class=\"kw-def\">voie commune</span> (prothrombinase → thrombine), qui transforme le <span class=\"kw-bio\">fibrinogène</span> en <span class=\"kw-bio\">fibrine</span>, stabilisée par le <span class=\"kw-bio\">FXIII</span>. <em>Cliquer un bouton pour mettre en évidence les acteurs touchés par la pathologie.</em> Source : fiche source EDN item 216 (Hémostase).\n        </figcaption>\n      </figure>\n      <p>Les facteurs de coagulation sont des proenzymes inactives (sauf le <span class=\"kw-bio\">FV</span> et le <span class=\"kw-bio\">FVIII</span>, cofacteurs). La cascade s'organise en deux voies :</p>\n      <table >\n        <thead><tr><th>Voie</th><th>Déclenchement</th><th>Test explorateur</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Voie extrinsèque</span><br>(= voie physiologique in vivo)</td><td>Déclenchée par le <span class=\"kw-bio\">facteur tissulaire (FT)</span> du vaisseau lésé, qui active le FVII</td><td><span class=\"kw-bio\">TQ / TP</span></td></tr>\n          <tr><td><span class=\"kw-def\">Voie intrinsèque / contact</span><br>(F12, F11, prékallicréine, KHPM)</td><td>Activée par le contact du sang avec une surface ; <strong>rôle mineur in vivo</strong> (déficit en F12 asymptomatique)</td><td><span class=\"kw-bio\">TCA</span></td></tr>\n          <tr><td><span class=\"kw-def\">Voie commune</span></td><td>Complexe prothrombinase (FXa + FVa + Ca²⁺ + phospholipides) → thrombine</td><td>TQ et <span class=\"kw-bio\">TCA</span></td></tr>\n        </tbody>\n      </table>\n      <p>La <span class=\"kw-bio\">thrombine (FIIa)</span> transforme le <span class=\"kw-bio\">fibrinogène</span> en <span class=\"kw-bio\">fibrine</span>, active les <span class=\"kw-alerte\">FV</span>, FVIII, FXI et la protéine C ; le <span class=\"kw-bio\">FXIII</span> consolide ensuite le caillot par des liaisons covalentes. Trois inhibiteurs physiologiques limitent la coagulation :</p>\n      <table >\n        <thead><tr><th>Inhibiteur</th><th>Cible</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Antithrombine</span></td><td>Thrombine (IIa) et FXa ; activité <strong>potentialisée 1000×</strong> par l'<span class=\"kw-ttt\">héparine</span></td></tr>\n          <tr><td><span class=\"kw-def\">Protéine C / protéine S</span></td><td>FVa et FVIIIa</td></tr>\n          <tr><td><span class=\"kw-def\">TFPI</span></td><td>FXa et FVIIa (inhibiteur de la voie d'initiation)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Facteurs <strong>vitamine K-dépendants</strong> : <span class=\"kw-bio\">F2, F7, F9, F10</span> (procoagulants) + <span class=\"kw-bio\">protéine C et protéine S</span> (inhibiteurs). Mnémo : « 1972 ».</div>\n\n      <p><strong>3 · <span class=\"kw-ttt\">Fibrinolyse</span></strong> — détruit le caillot une fois l'endothélium réparé.</p>\n      <p>Le <span class=\"kw-bio\">plasminogène</span> (proenzyme d'origine hépatique) est transformé en <span class=\"kw-bio\">plasmine</span> par les activateurs <span class=\"kw-bio\">t-PA</span> (synthétisé par les cellules endothéliales) et <span class=\"kw-bio\">u-PA</span> (urokinase). La plasmine dégrade la <span class=\"kw-bio\">fibrine</span> en <span class=\"kw-bio\">PDF</span> et en <span class=\"kw-bio\">D-dimères</span>. Inhibiteurs : <span class=\"kw-bio\">α2-antiplasmine</span> (principale), <span class=\"kw-bio\">PAI-1</span> (inhibe le t-PA) et <span class=\"kw-bio\">PAI-2</span> (synthétisé par le placenta, présent surtout chez la femme enceinte).</p>","frequence":0},{"id":"216-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les données d’interrogatoire et d’examen orientant vers le diagnostic du syndrome hémorragique et de sa cause","contenu":"<p>Devant un saignement, l'interrogatoire et l'examen visent deux objectifs : <strong>affirmer le syndrome <span class=\"kw-etio\">hémorragique</span></strong> et <strong>orienter vers sa cause</strong> (constitutionnelle <span class=\"kw-bio\">vs</span> <span class=\"kw-etio\">acquise</span>, niveau d'hémostase atteint).</p>\n      <p><strong>Interrogatoire — données orientantes :</strong></p>\n      <table >\n        <thead><tr><th>Donnée recherchée</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">ATCD familiaux de saignement</span></td><td>Cause <strong>constitutionnelle</strong> : hémophilie (transmission liée à l'X, garçons atteints) ; maladie de Willebrand (autosomique dominante, les 2 sexes)</td></tr>\n          <tr><td><span class=\"kw-clinique\">ATCD personnels hémorragiques</span></td><td>Saignement prolongé après <span class=\"kw-clinique\">extraction dentaire</span>, <span class=\"kw-clinique\">chirurgie</span> ou <span class=\"kw-clinique\">accouchement</span> (hémorragie de la délivrance) ; <span class=\"kw-clinique\">ménorragies depuis la puberté</span> ; épistaxis répétées</td></tr>\n          <tr><td><span class=\"kw-ttt\">Prises médicamenteuses</span></td><td>Antiplaquettaires ; <span class=\"kw-ttt\">anticoagulants</span> (<span class=\"kw-ttt\">AVK</span>, <span class=\"kw-ttt\">AOD</span>, héparines) ; <span class=\"kw-ttt\">AINS</span> ; <span class=\"kw-ttt\">ISRS</span></td></tr>\n          <tr><td>Caractères du saignement</td><td><strong>Spontané <span class=\"kw-bio\">vs</span> provoqué</strong> ; <strong>précoce <span class=\"kw-bio\">vs</span> retardé</strong> ; cutanéo-muqueux <span class=\"kw-bio\">vs</span> profond</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Examen — la sémiologie <span class=\"kw-etio\">hémorragique</span> oriente le niveau d'hémostase :</strong></p>\n      <table >\n        <thead><tr><th>Sémiologie</th><th>Caractéristiques</th><th>Niveau / causes évoquées</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Hémorragie cutanéo-muqueuse</span><br>(<span class=\"kw-def\">purpura</span>, <span class=\"kw-clinique\">ecchymoses</span>, gingivorragies, épistaxis, ménorragies)</td><td>Spontané et/ou provoqué ; précoce</td><td><strong>Hémostase primaire</strong> : thrombopénie ; thrombopathie ; maladie de Willebrand ; anomalie vasculaire</td></tr>\n          <tr><td><span class=\"kw-clinique\">Hémorragie profonde</span><br>(hématome, hémarthrose)</td><td>Provoqué par un traumatisme minime ; retardé</td><td><strong>Coagulation</strong> : hémophilie ; déficit en facteur</td></tr>\n          <tr><td><span class=\"kw-clinique\">Hémorragie viscérale</span><br>(<span class=\"kw-clinique\">méléna</span>, <span class=\"kw-clinique\">hématémèse</span>, <span class=\"kw-clinique\">hémoptysie</span>)</td><td>Souvent provoqué</td><td>Trouble de l'hémostase <strong>+ <span class=\"kw-clinique\">lésion</span> organique</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant.</strong> Le <span class=\"kw-alerte\">purpura thrombopénique</span> est <strong>plan, non infiltré</strong> ; le <span class=\"kw-alerte\">purpura vasculaire</span> est <strong>infiltré, palpable</strong>. Rechercher des <span class=\"kw-clinique\">télangiectasies</span> (nez, lèvres, doigts) évoquant une maladie de Rendu-Osler.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 214 — Thrombopénie · 215 — <span class=\"kw-def\">Purpura</span></em></p>","frequence":4},{"id":"216-4","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription des explorations biologiques devant une suspicion de syndrome hémorragique","contenu":"<p><strong>Bilan d'hémostase de 1ʳᵉ intention</strong> — 4 examens systématiques :</p>\n      <ul>\n        <li><span class=\"kw-bio\">NFS-plaquettes</span> — la numération plaquettaire fait partie de <strong>tout</strong> bilan d'hémostase.</li>\n        <li><span class=\"kw-bio\">TP (TQ)</span> — explore la voie extrinsèque + commune.</li>\n        <li><span class=\"kw-bio\">TCA</span> — explore la voie intrinsèque + commune.</li>\n        <li><span class=\"kw-bio\">Fibrinogène</span>.</li>\n      </ul>\n      <p>On y associe selon le contexte un <span class=\"kw-bio\">temps de saignement / temps d'occlusion plaquettaire (PFA-100)</span> pour explorer l'hémostase primaire. Modalité pré-analytique : prélèvement veineux sur tube <strong>citraté</strong> (chélateur du Ca²⁺), correctement rempli.</p>\n      <p><strong>Valeurs de référence :</strong></p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Valeur de référence</th><th>Anormal si</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">TCA</span></td><td><span class=\"kw-chiffre\">30-36 s</span></td><td>M &gt; <span class=\"kw-chiffre\">1,2 × T</span> (1,3 × T chez l'enfant)</td></tr>\n          <tr><td><span class=\"kw-bio\">TQ / TP</span></td><td><span class=\"kw-chiffre\">10-13 s</span> (<span class=\"kw-chiffre\">70-150 %</span>)</td><td>M &gt; <span class=\"kw-chiffre\">1,2 × T</span> ; <span class=\"kw-bio\">TP</span> &lt; <span class=\"kw-chiffre\">70 %</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Fibrinogène</span></td><td><span class=\"kw-chiffre\">2-4 g/L</span></td><td>&lt; <span class=\"kw-chiffre\">2 g/L</span> ou &gt; <span class=\"kw-chiffre\">4 g/L</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Facteurs de coagulation</span> (sauf FVIII)</td><td><span class=\"kw-chiffre\">70-150 %</span></td><td>&lt; <span class=\"kw-chiffre\">60 %</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Facteur Willebrand et FVIII</span></td><td><span class=\"kw-chiffre\">50-150 %</span></td><td>&lt; <span class=\"kw-chiffre\">50 %</span></td></tr>\n          <tr><td><span class=\"kw-bio\">D-dimères (ELISA)</span></td><td>&lt; <span class=\"kw-chiffre\">500 ng/mL</span></td><td>&gt; <span class=\"kw-chiffre\">500 ng/mL</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Orientation étiologique selon le trio TS / <span class=\"kw-bio\">TCA</span> / <span class=\"kw-bio\">TP</span> :</strong></p>\n      <table >\n        <thead><tr><th>TS</th><th><span class=\"kw-bio\">TCA</span></th><th><span class=\"kw-bio\">TP</span></th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td>Allongé</td><td>Normal</td><td>Normal</td><td>Thrombopénie ; thrombopathie ; anémie ; anomalie de la paroi vasculaire (<span class=\"kw-def\">vascularite</span>, Rendu-Osler, scorbut)</td></tr>\n          <tr><td>Normal</td><td>Allongé</td><td>Normal</td><td><span class=\"kw-alerte\">ACC</span> (anti-phospholipides) ; déficit ou <span class=\"kw-bio\">anticorps anti-facteur</span> de la voie intrinsèque (F8, F9, F11, F12)</td></tr>\n          <tr><td>Normal</td><td>Normal</td><td>Allongé</td><td>Déficit ou <span class=\"kw-bio\">anticorps anti-F7</span> ; <span class=\"kw-bio\">IHC</span> modérée ; carence en vitamine K débutante</td></tr>\n          <tr><td>Allongé</td><td>Allongé</td><td>Allongé</td><td><span class=\"kw-alerte\">CIVD</span> ; <span class=\"kw-ttt\">fibrinolyse</span> ; afibrinogénémie, hypo/dysfibrinogénémie</td></tr>\n          <tr><td>Normal</td><td>Allongé</td><td>Allongé</td><td>Déficit en facteur de la voie commune (F2, F5, F10) ; hypo/dysfibrinogénémie ; <span class=\"kw-def\">syndrome inflammatoire</span> majeur</td></tr>\n          <tr><td>Allongé</td><td>Allongé</td><td>Normal</td><td><span class=\"kw-def\">Maladie de Willebrand</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Tests de 2ᵉ intention</strong>, selon l'orientation :</p>\n      <ul>\n        <li><strong>Temps de thrombine :</strong> anomalie du <span class=\"kw-bio\">fibrinogène</span> ; présence d'une antithrombine (<span class=\"kw-ttt\">héparine</span>, <span class=\"kw-ttt\">dabigatran</span>).</li>\n        <li><strong>Épreuve de mélange</strong> (plasma malade + plasma témoin) : correction = déficit en facteur ; absence de correction = <span class=\"kw-ttt\">anticoagulant</span> circulant.</li>\n        <li><strong>Dosages spécifiques</strong> des facteurs de coagulation.</li>\n        <li><strong>Complexe Willebrand :</strong> vWF:RCo ; vWF:Ag ; FVIII:C.</li>\n        <li><strong>Temps de lyse des euglobulines</strong> (test de von Kaulla) : dépiste les hyperfibrinolyses.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 212 — <span class=\"kw-bio\">Hémogramme</span></em></p>","frequence":4},{"id":"216-5","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir demander un contrôle de la numération plaquettaire sur citrate devant une thrombopénie sans syndrome hémorragique","contenu":"<p>La numération plaquettaire de routine est réalisée sur tube <span class=\"kw-bio\">EDTA</span>. Chez environ <span class=\"kw-chiffre\">1 %</span> de la population, l'EDTA déclenche une <span class=\"kw-alerte\">agglutination des plaquettes in vitro</span> (agglutinines anti-EDTA) : le compteur automatisé compte les amas comme des cellules uniques et <strong>sous-estime</strong> le nombre de <span class=\"kw-bio\">plaquettes</span> — c'est la <span class=\"kw-alerte\">fausse thrombopénie</span> (pseudo-thrombopénie EDTA).</p>\n      <p><strong>Signe d'alerte :</strong> une <span class=\"kw-bio\">thrombopénie isolée</span>, découverte chez un patient <strong>sans aucun syndrome <span class=\"kw-etio\">hémorragique</span></strong>, doit faire évoquer en premier lieu une fausse thrombopénie.</p>\n      <p><strong>Conduite à tenir :</strong></p>\n      <ul>\n        <li>Demander un <strong>contrôle de la numération plaquettaire sur tube citraté</strong>.</li>\n        <li>Vérifier le <span class=\"kw-bio\">frottis sanguin</span> : la présence d'amas plaquettaires confirme la pseudo-thrombopénie.</li>\n        <li>Si la thrombopénie est <strong>confirmée sur citrate</strong> → c'est une vraie thrombopénie → bilan étiologique (cause centrale <span class=\"kw-bio\">vs</span> périphérique).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Ne jamais transfuser ni explorer lourdement une thrombopénie isolée avant d'avoir éliminé une fausse thrombopénie EDTA par un contrôle sur citrate.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 214 — Thrombopénie</em></p>","frequence":2},{"id":"216-6","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les valeurs de plaquettes, TCA, TP, fibrinogène associées à un risque d’hémorragie spontanée","contenu":"<p>L'objectif est de repérer en quelques minutes, sur le bilan d'hémostase, les patients à <span class=\"kw-alerte\">risque d'hémorragie spontanée</span> — c'est-à-dire un saignement survenant sans traumatisme.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Seuil critique</th><th>Conséquence et conduite</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Plaquettes</span></td><td>&lt; <span class=\"kw-chiffre\">20 G/L</span></td><td>Risque d'hémorragie spontanée majeur (<span class=\"kw-alerte\">hémorragie rétinienne, méningée</span>) ; transfusion de <span class=\"kw-bio\">plaquettes</span> si &lt; <span class=\"kw-chiffre\">20 G/L</span>, ou &lt; <span class=\"kw-chiffre\">50 G/L</span> en cas de saignement actif ou d'acte invasif</td></tr>\n          <tr><td><span class=\"kw-bio\">TP</span></td><td>&lt; <span class=\"kw-chiffre\">30 %</span></td><td>Risque <span class=\"kw-etio\">hémorragique</span> majeur ; PFC si <span class=\"kw-chiffre\">TP &lt; 40 %</span> + <span class=\"kw-alerte\">hémorragie active</span> ou acte invasif</td></tr>\n          <tr><td><span class=\"kw-bio\">Fibrinogène</span></td><td>&lt; <span class=\"kw-chiffre\">1 g/L</span></td><td>Risque <span class=\"kw-etio\">hémorragique</span> majeur ; concentrés de <span class=\"kw-bio\">fibrinogène</span> si saignement actif</td></tr>\n          <tr><td><span class=\"kw-bio\">TCA</span></td><td>Allongement franc</td><td>Traduit un déficit profond en facteur ; pas de seuil chiffré « spontané » mais impose une exploration urgente</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> L'association <span class=\"kw-alerte\">thrombopénie profonde + chute du fibrinogène + allongement du TCA et du TP</span> évoque une <strong><span class=\"kw-alerte\">CIVD</span> décompensée</strong> — situation à reconnaître sans délai.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 329 — Transfusion sanguine</em></p>","frequence":1},{"id":"216-7","rang":"B","rubrique":"Étiologies","titre":"Identifier les anomalies biologiques devant faire évoquer un déficit constitutionnel ou acquis en facteur de la coagulation","contenu":"<p>Devant un allongement du <span class=\"kw-bio\">TCA</span> et/ou du <span class=\"kw-bio\">TP</span>, la démarche distingue un <strong>déficit en facteur</strong> d'un <strong><span class=\"kw-ttt\">anticoagulant</span> circulant (ACC)</strong>. L'étape pivot est l'<span class=\"kw-bio\">épreuve de mélange</span> (plasma du malade + plasma témoin) : <strong>correction</strong> = déficit en facteur ; <strong>absence de correction</strong> = ACC.</p>\n\n      <p><strong>1 · Allongement isolé du <span class=\"kw-bio\">TCA</span></strong> (<span class=\"kw-bio\">TP</span> normal) :</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td>Temps de thrombine <strong>augmenté</strong></td><td>Présence d'<span class=\"kw-ttt\">héparine</span> (<span class=\"kw-ttt\">HNF</span>, ou contamination du prélèvement)</td></tr>\n          <tr><td>TT normal + épreuve de mélange <strong>corrigée</strong></td><td>Déficit en facteur de la voie intrinsèque : <span class=\"kw-bio\">F8</span> (hémophilie A), <span class=\"kw-bio\">F9</span> (hémophilie B), <span class=\"kw-bio\">F11</span> (maladie de Rosenthal) = risque <span class=\"kw-etio\">hémorragique</span> ; <span class=\"kw-bio\">F12</span> = asymptomatique</td></tr>\n          <tr><td>TT normal + épreuve de mélange <strong>non corrigée</strong></td><td><span class=\"kw-alerte\">ACC</span> : anti-phospholipides (ACC lupique = risque <span class=\"kw-etio\">thrombotique</span>) ; ou <span class=\"kw-bio\">anticorps anti-F8</span> / anti-F9</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>2 · Allongement isolé du <span class=\"kw-bio\">TP</span> / TQ</strong> (<span class=\"kw-bio\">TCA</span> normal) :</p>\n      <table >\n        <thead><tr><th>Épreuve de mélange</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Corrigée</strong></td><td>Déficit en <span class=\"kw-bio\">F7</span> : constitutionnel (rare) ou <span class=\"kw-etio\">acquis</span> — hypovitaminose K débutante, <span class=\"kw-bio\">IHC</span> modérée, initiation d'<span class=\"kw-ttt\">AVK</span> (le F7 a la demi-vie la plus courte, ~<span class=\"kw-chiffre\">6-8 h</span>)</td></tr>\n          <tr><td><strong>Non corrigée</strong></td><td>Auto-<span class=\"kw-bio\">anticorps anti-F7</span></td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>3 · Allongement du <span class=\"kw-bio\">TCA</span> ET du <span class=\"kw-bio\">TP</span> :</strong></p>\n      <table >\n        <thead><tr><th>Étape</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td>TT augmenté → doser le <span class=\"kw-bio\">fibrinogène</span></td><td><strong>Diminué :</strong> hypo/afibrinogénémie (<span class=\"kw-alerte\">CIVD</span>, <span class=\"kw-ttt\">fibrinolyse</span>, <span class=\"kw-bio\">IHC</span>)<br><strong>Normal :</strong> dysfibrinogénémie<br><strong>Augmenté :</strong> <span class=\"kw-def\">syndrome inflammatoire</span> majeur</td></tr>\n          <tr><td>TT normal + mélange <strong>corrigé</strong></td><td>Déficit de la voie commune (F2, F5, F10) ; hypovitaminose K avancée ; <span class=\"kw-bio\">IHC</span></td></tr>\n          <tr><td>TT normal + mélange <strong>non corrigé</strong></td><td><span class=\"kw-alerte\">ACC</span> anti-F2 / anti-F5 / anti-F10</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Déficits constitutionnels — maladie de Willebrand <span class=\"kw-bio\">vs</span> hémophilie :</strong></p>\n      <table >\n        <thead><tr><th>&nbsp;</th><th>Maladie de Willebrand</th><th>Hémophilie</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td>Fréquente (~<span class=\"kw-chiffre\">1 %</span>) — pathologie constitutionnelle de l'hémostase la plus fréquente</td><td>Rare (<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> g</span>arçon sur <span class=\"kw-chiffre\">5000</span>)</td></tr>\n          <tr><td><strong>Transmission</strong></td><td><span class=\"kw-etio\">Autosomique dominante</span> ; les 2 sexes</td><td><span class=\"kw-etio\">Récessive liée à l'X</span> ; garçons atteints, femmes conductrices ;<span class=\"kw-chiffre\"> 30 %</span> de mutations de novo</td></tr>\n          <tr><td><strong>Étiologie</strong></td><td>Déficit quantitatif ou qualitatif en <span class=\"kw-bio\">vWF</span></td><td>Déficit isolé en <span class=\"kw-bio\">F8</span> (hémophilie A,<span class=\"kw-chiffre\"> 85 %</span>) ou <span class=\"kw-bio\">F9</span> (hémophilie B,<span class=\"kw-chiffre\"> 15 %</span>)</td></tr>\n          <tr><td><strong>Clinique</strong></td><td>Hémorragies cutanéo-muqueuses : ménorragies +++, hémorragies amygdaliennes (évocatrices)</td><td>Hémorragies profondes : hémarthroses, hématomes</td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span class=\"kw-bio\">TS et TCA allongés</span> ; <span class=\"kw-bio\">TP</span> normal</td><td><span class=\"kw-bio\">TCA allongé isolé, corrigé par le plasma témoin</span> ; TS et <span class=\"kw-bio\">TP</span> normaux</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Déficits <span class=\"kw-etio\">acquis</span> — hypovitaminose K <span class=\"kw-bio\">vs</span> <span class=\"kw-alerte\">insuffisance hépatocellulaire</span> (<span class=\"kw-bio\">IHC</span>) :</strong></p>\n      <table >\n        <thead><tr><th>&nbsp;</th><th>Hypovitaminose K</th><th>Insuffisance hépatocellulaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Facteurs</strong></td><td>↓ <span class=\"kw-bio\">F2, F7, F9, F10</span> (vitamine K-dépendants)</td><td>↓ facteurs vitamine K-dépendants <strong>ET</strong> ↓ <span class=\"kw-bio\">FV</span></td></tr>\n          <tr><td><strong>Facteur V</strong></td><td><span class=\"kw-bio\">Normal</span></td><td><span class=\"kw-alerte\">Diminué</span> (<span class=\"kw-alerte\">signe de gravité</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Fibrinogène</span> / <span class=\"kw-bio\">plaquettes</span></strong></td><td>Normaux</td><td><span class=\"kw-bio\">Fibrinogène</span> ↓ si sévère ; ± thrombopénie (hypersplénisme)</td></tr>\n          <tr><td><strong>Causes</strong></td><td><span class=\"kw-etio\">AVK</span> ; ATB (destruction de la flore) ; carence d'apport ; malabsorption / cholestase</td><td>Hépatopathie aiguë ou chronique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant clé.</strong> Le <strong>facteur V</strong> sépare les deux : <span class=\"kw-bio\">normal</span> dans l'hypovitaminose K, <span class=\"kw-alerte\">abaissé</span> dans l'<span class=\"kw-bio\">IHC</span>. Devant tout déficit en F8 : vérifier le vWF (un Willebrand peut mimer une hémophilie A) et rechercher un <span class=\"kw-alerte\">anticorps anti-F8</span> (hémophilie <span class=\"kw-etio\">acquise</span> — sujet âgé ou post-partum, <span class=\"kw-bio\">TCA</span> non corrigé par le plasma témoin, F8 effondré).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP</em></p>","frequence":11},{"id":"216-8","rang":"B","rubrique":"Étiologies","titre":"Identifier les signes orientant vers une thrombopathie","contenu":"<p>Une <span class=\"kw-def\">thrombopathie</span> est une anomalie <strong>fonctionnelle</strong> des <span class=\"kw-bio\">plaquettes</span> : la <span class=\"kw-bio\">numération plaquettaire est normale</span>.</p>\n      <p><strong>Quand l'évoquer :</strong> devant des <span class=\"kw-clinique\">saignements cutanéo-muqueux inexpliqués</span> avec <span class=\"kw-bio\">numération plaquettaire normale</span>, <span class=\"kw-bio\">TCA et TP normaux</span>, mais <span class=\"kw-bio\">TS / temps d'occlusion plaquettaire (PFA-100) allongé</span>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Acquises</strong><br>(les plus fréquentes)</td><td><span class=\"kw-etio\">Insuffisance rénale</span> ; <span class=\"kw-ttt\">médicaments</span> +++ (<span class=\"kw-ttt\">aspirine</span>, <span class=\"kw-ttt\">AINS</span>, thiénopyridines — <span class=\"kw-ttt\">clopidogrel</span>, <span class=\"kw-ttt\">prasugrel</span> —, <span class=\"kw-ttt\">ticagrelor</span>, <span class=\"kw-ttt\">ISRS</span>, pénicillines à forte dose) ; <span class=\"kw-etio\">hémopathies</span> (SMP, SMD, gammapathies monoclonales — myélome, maladie de Waldenström)</td></tr>\n          <tr><td><strong>Constitutionnelles</strong><br>(rares ; enfant avec ATCD familiaux)</td><td><span class=\"kw-def\">Syndrome de Bernard-Soulier</span> (déficit en GPIb-IX → adhérence) ; <span class=\"kw-def\">thrombasthénie de Glanzmann</span> (déficit en GPIIb-IIIa → agrégation) ; anomalies des pools/granules ; déficits enzymatiques</td></tr>\n        </tbody>\n      </table>\n      <p>Le diagnostic repose sur l'<span class=\"kw-bio\">agrégométrie</span> (test de référence des fonctions plaquettaires) et la <span class=\"kw-bio\">cytométrie de flux</span> (récepteurs membranaires).</p>\n      <div class=\"callout callout-warn\"><strong>Discriminant.</strong> Devant un saignement cutanéo-muqueux avec <span class=\"kw-bio\">NFS</span> et bilan de coagulation normaux, c'est le <strong>TS / PFA-100 allongé</strong> qui met sur la voie de la thrombopathie. Toujours chercher en premier une cause <span class=\"kw-etio\">acquise</span> médicamenteuse.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 214 — Thrombopénie</em></p>","frequence":1},{"id":"216-9","rang":"B","rubrique":"Étiologies","titre":"Identifier une CIVD et connaître les étiologies les plus fréquentes","contenu":"<p>La <span class=\"kw-def\">CIVD</span> (<span class=\"kw-alerte\">coagulation intravasculaire disséminée</span>) est une <span class=\"kw-alerte\">défaillance</span> du système de coagulation : activation <strong>simultanée et excessive</strong> de la <span class=\"kw-bio\">coagulation</span> et de la <span class=\"kw-bio\">fibrinolyse</span> → consommation des facteurs + déplétion des inhibiteurs + thrombopénie de consommation.</p>\n      <p><strong><span class=\"kw-def\">Physiopathologie</span> :</strong> elle est déclenchée par une <span class=\"kw-etio\">expression excessive de facteur tissulaire</span> (<span class=\"kw-bio\">monocytes</span> infectés, endothélium lésé, organes riches en FT lésés — placenta, prostate, poumon — ou cellules tumorales) → activation systémique de la coagulation → microthrombi diffus (consommation) et hyperfibrinolyse secondaire.</p>\n      <p><strong>Étiologies les plus fréquentes :</strong></p>\n      <table >\n        <thead><tr><th>Contexte</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Sepsis</span></strong></td><td><span class=\"kw-etio\">1ʳᵉ cause de CIVD</span> (surtout bactéries Gram −) ; complique <span class=\"kw-chiffre\">~30 %</span> des <span class=\"kw-def\">sepsis</span> ; <span class=\"kw-def\">choc septique</span>, <span class=\"kw-def\">purpura</span> fulminans</td></tr>\n          <tr><td><strong>Obstétrical</strong></td><td><span class=\"kw-etio\">Hématome rétroplacentaire</span> ; embolie amniotique ; mort fœtale in utero ; môle hydatiforme ; éclampsie</td></tr>\n          <tr><td><strong>Cancers et hémopathies</strong></td><td>Cancers métastasés (poumon, pancréas, prostate) ; <span class=\"kw-etio\">LAM3</span></td></tr>\n          <tr><td><strong>Lésions tissulaires / lyse cellulaire</strong></td><td>Polytraumatisme ; brûlures étendues ; <span class=\"kw-def\">pancréatite aiguë</span> ; rhabdomyolyse ; hémolyse intravasculaire ; accident transfusionnel ABO</td></tr>\n          <tr><td><strong>Autres</strong></td><td>Venin de serpent ; accès palustre à <em>P. falciparum</em> ; circulation extra-corporelle ; hypo/<span class=\"kw-clinique\">hyperthermie</span> maligne</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Présentation clinique :</strong> <span class=\"kw-clinique\">CIVD hémorragique</span> (surtout obstétricale — saignements en nappe diffus) ou <span class=\"kw-clinique\">CIVD thrombotique</span> (surtout infectieuse — microthromboses, <span class=\"kw-alerte\">défaillance multiviscérale</span>, <span class=\"kw-def\">purpura</span> fulminans, <span class=\"kw-clinique\">gangrène</span> des extrémités).</p>\n      <p><strong>Anomalies biologiques</strong> — aucune n'est constante ni pathognomonique. Les plus précoces et caractéristiques sont la <span class=\"kw-bio\">thrombopénie</span> et l'<span class=\"kw-bio\">hypofibrinogénémie</span> ; s'y associent l'allongement du <span class=\"kw-bio\">TCA</span> et du TQ, la diminution des facteurs (F2, F5, F7, F10 — <strong>et F8</strong>, contrairement à l'<span class=\"kw-bio\">IHC</span>), l'augmentation des <span class=\"kw-bio\">PDF / D-dimères / monomères de fibrine</span>, des <span class=\"kw-bio\">complexes solubles présents</span> et un <span class=\"kw-bio\">test à l'éthanol positif</span>.</p>\n      <p><strong>Définition <span class=\"kw-ttt\">biologique</span> de la <span class=\"kw-alerte\">CIVD</span></strong> — <span class=\"kw-bio\">D-dimères &gt; 500 µg/L</span> associés à <strong>1 <span class=\"kw-def\">critère majeur</span> OU 2 critères mineurs</strong> :</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Critère majeur</th><th><span class=\"kw-def\">Critère mineur</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Plaquettes</span></td><td>≤ <span class=\"kw-chiffre\">50 G/L</span></td><td><span class=\"kw-chiffre\">]50 ; 100]</span> G/L</td></tr>\n          <tr><td><span class=\"kw-bio\">TP</span></td><td>&lt; <span class=\"kw-chiffre\">50 %</span></td><td><span class=\"kw-chiffre\">[50 ; 65[</span> %</td></tr>\n          <tr><td><span class=\"kw-bio\">Fibrinogène</span></td><td>—</td><td>&lt; <span class=\"kw-chiffre\">1 g/L</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le <span class=\"kw-def\">score</span> ISTH ≥ <span class=\"kw-chiffre\">5</span> définit une <span class=\"kw-alerte\">CIVD</span> <strong>décompensée</strong> ; &lt; <span class=\"kw-chiffre\">5</span> une <span class=\"kw-alerte\">CIVD</span> <strong>compensée</strong> (analyses à répéter à<span class=\"kw-chiffre\"> 24 h</span>).</p>\n      <p><strong>Diagnostics différentiels :</strong></p>\n      <table >\n        <thead><tr><th>Paramètre</th><th><span class=\"kw-alerte\">CIVD</span></th><th><span class=\"kw-ttt\">Fibrinolyse</span> primitive</th><th><span class=\"kw-bio\">IHC</span></th><th>Hypovitaminose K</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Plaquettes</span></td><td>Diminuées</td><td>Normales</td><td>Normales (± ↓ si hypersplénisme)</td><td>Normales</td></tr>\n          <tr><td><span class=\"kw-bio\">Facteur V</span></td><td>Diminué</td><td>Diminué</td><td>Diminué</td><td>Normal</td></tr>\n          <tr><td><span class=\"kw-bio\">Facteur VIII</span></td><td>Diminué</td><td>Diminué</td><td>Normal</td><td>Normal</td></tr>\n          <tr><td><span class=\"kw-bio\">Fibrinogène</span></td><td>Diminué</td><td>Diminué</td><td>Diminué</td><td>Normal</td></tr>\n          <tr><td><span class=\"kw-bio\">D-dimères / PDF</span></td><td>Augmentés</td><td>Augmentés</td><td>Normaux</td><td>Normaux</td></tr>\n          <tr><td>Complexes solubles / test à l'éthanol</td><td>Présents / positif</td><td>Absents / négatif</td><td>Absents / négatif</td><td>Absents / négatif</td></tr>\n          <tr><td>Temps de lyse des euglobulines</td><td>Normal</td><td>Raccourci</td><td>Normal</td><td>Normal</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminants clés.</strong> Les <span class=\"kw-bio\">plaquettes</span> sont <strong>diminuées seulement</strong> dans la <span class=\"kw-alerte\">CIVD</span> ; les complexes solubles et le test à l'éthanol sont <strong>positifs seulement</strong> dans la <span class=\"kw-alerte\">CIVD</span> ; le <span class=\"kw-bio\">FV est normal</span> dans l'hypovitaminose K ; le <span class=\"kw-bio\">FVIII est normal</span> dans l'<span class=\"kw-bio\">IHC</span> ; un <span class=\"kw-bio\">temps de lyse des euglobulines raccourci</span> avec une numération plaquettaire <strong>normale</strong> oriente vers une <span class=\"kw-ttt\">fibrinolyse</span> aiguë primitive.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 329 — Transfusion sanguine</em></p>","frequence":5}],"astuces":[],"strategie":{"urgence":"<p><strong>Seuils transfusionnels <span class=\"q\">— risque d'hémorragie spontanée</span></strong></p><p><span class=\"kw-ttt\">transfusion de plaquettes</span> si <span class=\"kw-chiffre\">&lt; 20 G/L</span> (ou <span class=\"kw-chiffre\">&lt; 50 G/L</span> si saignement actif / acte invasif)</p><ul><li><span class=\"kw-bio\">Plaquettes</span> <span class=\"kw-chiffre\">&lt; 20 G/L</span> → risque d'<span class=\"kw-alerte\">hémorragie spontanée</span> majeur</li><li><span class=\"kw-bio\">TP</span> <span class=\"kw-chiffre\">&lt; 30 %</span> → risque <span class=\"kw-alerte\">hémorragique</span> majeur</li><li><span class=\"kw-bio\">Fibrinogène</span> <span class=\"kw-chiffre\">&lt; 1 g/L</span> → risque <span class=\"kw-alerte\">hémorragique</span> majeur</li></ul><p><strong><span class=\"kw-alerte\">CIVD</span> décompensée <span class=\"q\">— à reconnaître sans délai</span></strong></p><p>traitement <span class=\"kw-ttt\">étiologique</span> urgent + <span class=\"kw-ttt\">CPA</span> / <span class=\"kw-ttt\">PFC</span> selon les seuils</p><ul><li><span class=\"kw-alerte\">Thrombopénie</span> + <span class=\"kw-alerte\">hypofibrinogénémie</span> + allongement du <span class=\"kw-bio\">TCA</span> et du <span class=\"kw-bio\">TP</span></li><li><span class=\"kw-def\">Score</span> ISTH <span class=\"kw-chiffre\">≥ 5</span> = <span class=\"kw-alerte\">CIVD</span> décompensée</li></ul><p><strong>Hémorragie sur <span class=\"kw-ttt\">AVK</span> / hypovitaminose K</strong></p><p>le <span class=\"kw-bio\">F7</span> chute le premier (demi-vie <span class=\"kw-chiffre\">~6–8 h</span>) → <span class=\"kw-bio\">TP</span> abaissé précocement</p><ul><li><span class=\"kw-ttt\">Vitamine K1</span> IV lente : correction des anomalies en <span class=\"kw-chiffre\">6–12 h</span></li><li><span class=\"kw-ttt\">PPSB</span> (complexe prothrombinique) si hémorragie grave : effet en <span class=\"kw-chiffre\">30 min</span></li></ul>","redflags":"<ul><li><span class=\"kw-bio\">Plaquettes</span> <span class=\"kw-chiffre\">&lt; 20 G/L</span> → <span class=\"kw-alerte\">hémorragie spontanée</span> (rétinienne, méningée)</li><li><span class=\"kw-def\">CIVD</span> décompensée : <span class=\"kw-alerte\">défaillance multiviscérale</span>, <span class=\"kw-def\">purpura fulminans</span>, <span class=\"kw-clinique\">gangrène</span> des extrémités</li><li><span class=\"kw-bio\">Facteur V abaissé</span> → <span class=\"kw-alerte\">insuffisance hépatocellulaire</span> sévère</li><li>Hémophilie — hématomes graves par leur siège : <span class=\"kw-alerte\">plancher de la bouche</span> (<span class=\"kw-alerte\">asphyxie</span>), <span class=\"kw-alerte\">loge antérieure de l'avant-bras</span> (<span class=\"kw-clinique\">syndrome de Volkmann</span>), <span class=\"kw-alerte\">rétro-orbitaire</span> (cécité), <span class=\"kw-alerte\">hématome intracrânien</span></li><li><span class=\"kw-def\">Hémophilie acquise</span> (<span class=\"kw-bio\">anticorps anti-F8</span>) : saignements inexpliqués chez le <span class=\"kw-alerte\">sujet âgé</span> ou en <span class=\"kw-alerte\">post-partum</span> (<span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">8–20 %</span>)</li><li>Hypovitaminose K du <span class=\"kw-clinique\">nouveau-né</span> : <span class=\"kw-alerte\">risque d'hémorragie méningée</span></li></ul>","principes":"<p>Le traitement est avant tout <span class=\"kw-ttt\">étiologique</span>. Mesures communes à tout <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">hémorragique</span></span> : <span class=\"kw-ci\">proscrire anticoagulants, AINS et antiagrégants plaquettaires</span>, <span class=\"kw-ci\">injections intramusculaires</span> et <span class=\"kw-ci\">rasage manuel</span> ; <span class=\"kw-ttt\">blocage préventif des règles</span>.</p><p><strong><span class=\"kw-alerte\">CIVD</span></strong></p><p><span class=\"kw-ci\">complexe prothrombinique (CCP / PPSB) contre-indiqué</span> (risque d'aggravation <span class=\"kw-etio\">thrombotique</span>)</p><ul><li>Traitement <span class=\"kw-ttt\">étiologique</span> fondamental ++</li><li><span class=\"kw-ttt\">CPA</span> si <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-chiffre\">&lt; 50 G/L</span> ET acte invasif / <span class=\"kw-alerte\">hémorragie active</span></li><li><span class=\"kw-ttt\">PFC</span> (± <span class=\"kw-ttt\">concentrés de fibrinogène</span>) si <span class=\"kw-bio\">TP</span> <span class=\"kw-chiffre\">&lt; 40 %</span> ET acte invasif / <span class=\"kw-alerte\">hémorragie active</span></li></ul><p><strong>Hypovitaminose K</strong></p><p>chez le nouveau-né : <span class=\"kw-ttt\">vitamine K1 2 mg per os</span> à la naissance et entre J4–<span class=\"kw-chiffre\">J7</span></p><ul><li><span class=\"kw-ttt\">Vitamine K1</span> per os ou IV lente (correction en <span class=\"kw-chiffre\">6–12 h</span>)</li><li><span class=\"kw-ttt\">PPSB</span> si hémorragie grave (effet en <span class=\"kw-chiffre\">30 min</span>)</li></ul><p><strong>Hémophilie constitutionnelle</strong></p><p>risque majeur = <span class=\"kw-alerte\">inhibiteur anti-F8 / anti-F9</span> (à suspecter devant toute inefficacité du traitement)</p><ul><li>Injection de <span class=\"kw-ttt\">concentrés de F8</span> (hémophilie A) ou <span class=\"kw-ttt\">de F9</span> (hémophilie B), ou <span class=\"kw-ttt\">émicizumab</span></li><li><span class=\"kw-ttt\">Desmopressine (DDAVP)</span> possible dans les formes mineures d'hémophilie A si bon répondeur</li><li><span class=\"kw-def\">Suivi</span> en <span class=\"kw-ttt\">centre spécialisé</span> ; <span class=\"kw-ci\">pas d'IM</span>, <span class=\"kw-ci\">pas d'aspirine ni AINS</span></li></ul><p><strong>Maladie de Willebrand</strong></p><p><span class=\"kw-ci\">CI des antiplaquettaires et anticoagulants</span> ; <span class=\"kw-ci\">pas d'injection IM</span></p><ul><li><span class=\"kw-ttt\">Desmopressine (DDAVP)</span> IV ou nasale en 1re intention (type 1), avec <span class=\"kw-ci\">restriction hydrique</span> pour prévenir l'hyponatrémie</li><li><span class=\"kw-ttt\">Concentrés de vWF</span> purifié IV en 2nde intention si DDAVP inefficace</li></ul><p><strong>Hémophilie <span class=\"kw-etio\">acquise</span> (<span class=\"kw-bio\">anticorps anti-F8</span>)</strong></p><p>rechercher systématiquement un <span class=\"kw-alerte\">anticorps anti-F8</span> devant tout déficit en F8 chez l'adulte</p><ul><li>Court-circuiter l'inhibiteur : <span class=\"kw-ttt\">rFVIIa (Novoseven)</span> ou <span class=\"kw-ttt\">CCP activé</span></li><li>Inhiber la synthèse de l'auto-anticorps : <span class=\"kw-ttt\">corticoïdes + cyclophosphamide</span> ou <span class=\"kw-ttt\">rituximab</span></li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/disseminated-intravascular-coagulation","label":"Radiopaedia : Disseminated intravascular coagulation"},{"href":"https://radiopaedia.org/articles/hereditary-haemorrhagic-telangiectasia","label":"Radiopaedia : Hereditary haemorrhagic telangiectasia"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Bilan d'hémostase : quel paramètre est anormal ? — Bilan de 1re intention : NFS-plaquettes + TCA + TP + fibrinogène (± TS / PFA-100)","detail":"<h4>CAT — orientation étiologique d'un <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">hémorragique</span></span> — Tri sur le bilan d'hémostase : <span class=\"kw-bio\">NFS</span>-<span class=\"kw-bio\">plaquettes</span>, <span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">fibrinogène</span></h4>","branches":[{"to":"q-thrombopenie","label":"Plaquettes basses (thrombopénie)","color":"blue"},{"to":"q-primaire","label":"TS / PFA-100 allongé · NFS, TCA, TP normaux","color":"blue"},{"to":"q-tca","label":"TCA allongé isolé · TP normal","color":"blue"},{"to":"t-f7","label":"TP allongé isolé · TCA normal","color":"blue"},{"to":"q-tca-tp","label":"TCA + TP allongés","color":"blue"}]},{"id":"q-thrombopenie","kind":"decision","label":"Syndrome hémorragique associé ? — Thrombopénie isolée sans saignement = penser d'abord à une fausse thrombopénie EDTA","branches":[{"to":"t-fausse-tp","label":"Aucun saignement → contrôle sur citrate","color":"amber"},{"to":"t-thrombopenie","label":"Vraie thrombopénie (confirmée sur citrate)","color":"red"}]},{"id":"t-fausse-tp","kind":"terminal","label":"Fausse thrombopénie (EDTA)","color":"amber","detail":"<h4>Confirmation</h4><ul><li>Contrôle de la numération sur tube <span class=\"kw-bio\">citraté</span> ; <span class=\"kw-bio\">frottis sanguin</span> : présence d'amas plaquettaires</li></ul><h4>Mécanisme</h4><ul><li>Agglutination des <span class=\"kw-bio\">plaquettes</span> in vitro par les <span class=\"kw-etio\">agglutinines anti-EDTA</span> (~<span class=\"kw-chiffre\">1 %</span> de la population) → le compteur sous-estime les <span class=\"kw-bio\">plaquettes</span></li></ul><h4>Piège</h4><ul><li>Ne jamais transfuser ni explorer lourdement une <span class=\"kw-bio\">thrombopénie isolée</span> sans saignement avant d'avoir éliminé une fausse thrombopénie sur citrate</li></ul>"},{"id":"t-thrombopenie","kind":"terminal","label":"Thrombopénie vraie","color":"red","detail":"<h4>Confirmation</h4><ul><li>Thrombopénie confirmée sur <span class=\"kw-bio\">citrate</span> → bilan étiologique (cause centrale <span class=\"kw-bio\">vs</span> périphérique)</li></ul><h4>Gravité</h4><ul><li><span class=\"kw-alerte\">Plaquettes &lt; 20 G/L</span> → risque d'<span class=\"kw-alerte\">hémorragie spontanée</span> (rétinienne, méningée)</li></ul><h4>Renvoi</h4><ul><li>Item 214 (thrombopénie)</li></ul>"},{"id":"q-primaire","kind":"decision","label":"TCA associé ? — Numération plaquettaire normale ; agrégométrie ou complexe Willebrand selon le TCA","branches":[{"to":"t-thrombopathie","label":"TCA normal","color":"amber"},{"to":"t-willebrand","label":"TCA allongé","color":"amber"}]},{"id":"t-thrombopathie","kind":"terminal","label":"Thrombopathie","color":"amber","detail":"<h4>Quand l'évoquer</h4><ul><li>Saignements <span class=\"kw-clinique\">cutanéo-muqueux</span> avec <span class=\"kw-bio\">numération plaquettaire normale</span>, <span class=\"kw-bio\">TCA et TP normaux</span>, mais <span class=\"kw-bio\">TS / PFA-100 allongé</span></li></ul><h4>Étiologies</h4><ul><li>Acquises (les plus fréquentes) : <span class=\"kw-ttt\">médicaments</span> +++ (<span class=\"kw-ttt\">aspirine</span>, <span class=\"kw-ttt\">AINS</span>, thiénopyridines, <span class=\"kw-ttt\">ISRS</span>), <span class=\"kw-etio\">insuffisance rénale</span>, <span class=\"kw-etio\">hémopathies</span> (SMP, SMD, gammapathies)</li><li>Constitutionnelles (rares) : <span class=\"kw-def\">syndrome de Bernard-Soulier</span> (GPIb-IX), <span class=\"kw-def\">thrombasthénie de Glanzmann</span> (GPIIb-IIIa)</li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-bio\">Agrégométrie</span> (test de référence) ; <span class=\"kw-bio\">cytométrie de flux</span> (récepteurs membranaires)</li></ul><h4>Renvoi</h4><ul><li>Item 214 (thrombopénie)</li></ul>"},{"id":"t-willebrand","kind":"terminal","label":"Maladie de Willebrand","color":"amber","detail":"<h4>Confirmation</h4><ul><li>Complexe Willebrand : <span class=\"kw-bio\">vWF:RCo</span>, <span class=\"kw-bio\">vWF:Ag</span>, <span class=\"kw-bio\">FVIII:C</span> ; <span class=\"kw-def\">classification</span> en types 1 / 2 / 3</li></ul><h4>Clinique</h4><ul><li>Hémorragies <span class=\"kw-clinique\">cutanéo-muqueuses</span> : <span class=\"kw-clinique\">ménorragies</span> +++ (les plus fréquentes), <span class=\"kw-clinique\">hémorragies amygdaliennes</span> (les plus évocatrices)</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">TS et TCA allongés</span>, <span class=\"kw-bio\">TP normal</span> ; pathologie constitutionnelle de l'hémostase la plus fréquente (~<span class=\"kw-chiffre\">1 %</span>)</li></ul><h4>PEC</h4><ul><li><span class=\"kw-ttt\">Desmopressine (DDAVP)</span> IV/nasale (type 1, avec <span class=\"kw-ci\">restriction hydrique</span>) ; <span class=\"kw-ttt\">concentrés de vWF</span> en 2nde intention</li></ul>"},{"id":"q-tca","kind":"decision","label":"Temps de thrombine + épreuve de mélange ? — TT augmenté → évoquer une héparine ; TT normal → épreuve de mélange (plasma malade + témoin)","branches":[{"to":"t-deficit-intr","label":"TT normal · TCA corrigé par le témoin","color":"amber"},{"to":"t-acc","label":"TT normal · TCA non corrigé","color":"red"}]},{"id":"t-deficit-intr","kind":"terminal","label":"Déficit en facteur de la voie intrinsèque","color":"amber","detail":"<h4>Mécanisme</h4><ul><li>TT normal + <span class=\"kw-bio\">épreuve de mélange corrigée</span> = déficit en facteur (un <span class=\"kw-bio\">TT augmenté</span> aurait évoqué une <span class=\"kw-ttt\">héparine</span> dans le prélèvement)</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-def\">Hémophilie A</span> : déficit en <span class=\"kw-bio\">F8</span> (<span class=\"kw-chiffre\">85 %</span>)</li><li><span class=\"kw-def\">Hémophilie B</span> : déficit en <span class=\"kw-bio\">F9</span> (<span class=\"kw-chiffre\">15 %</span>)</li><li><span class=\"kw-def\">Maladie de Rosenthal</span> : déficit en <span class=\"kw-bio\">F11</span></li><li>Déficit en <span class=\"kw-bio\">F12</span> : asymptomatique (<span class=\"kw-bio\">TCA</span> allongé sans risque <span class=\"kw-etio\">hémorragique</span>)</li></ul><h4>Réflexe</h4><ul><li>Devant tout déficit en <span class=\"kw-bio\">F8</span> : vérifier le <span class=\"kw-bio\">vWF</span> (un Willebrand peut mimer une hémophilie A) et rechercher un <span class=\"kw-alerte\">anticorps anti-F8</span></li></ul>"},{"id":"t-acc","kind":"terminal","label":"Anticoagulant circulant (ACC)","color":"red","detail":"<h4>Mécanisme</h4><ul><li>TT normal + <span class=\"kw-bio\">épreuve de mélange non corrigée</span> = <span class=\"kw-ttt\">anticoagulant</span> circulant</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-alerte\">ACC de type anti-phospholipides</span> (anti-cardiolipine, anti-β<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span>G</span>P1) = risque <span class=\"kw-alerte\">thrombotique</span>, pas <span class=\"kw-etio\">hémorragique</span></li><li><span class=\"kw-alerte\">Hémophilie acquise</span> : <span class=\"kw-bio\">anticorps anti-F8</span> (sujet âgé / post-partum), <span class=\"kw-bio\">F8 effondré</span></li></ul><h4>Conduite (hémophilie <span class=\"kw-etio\">acquise</span>)</h4><ul><li><span class=\"kw-ttt\">rFVIIa</span> ou <span class=\"kw-ttt\">CCP activé</span> + immunomodulateur (<span class=\"kw-ttt\">corticoïdes + cyclophosphamide</span> ou <span class=\"kw-ttt\">rituximab</span>)</li></ul>"},{"id":"t-f7","kind":"terminal","label":"Déficit en facteur VII (voie extrinsèque)","color":"amber","detail":"<h4>Mécanisme</h4><ul><li><span class=\"kw-bio\">TP allongé isolé</span>, <span class=\"kw-bio\">TCA normal</span> ; épreuve de mélange corrigée = déficit en <span class=\"kw-bio\">F7</span> (demi-vie la plus courte, <span class=\"kw-chiffre\">~6–8 h</span>)</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Hypovitaminose K débutante</span></li><li><span class=\"kw-etio\">Insuffisance hépatocellulaire modérée</span></li><li>Initiation d'un traitement par <span class=\"kw-ttt\">AVK</span></li><li>Déficit constitutionnel en F7 (rare) ou auto-<span class=\"kw-bio\">anticorps anti-F7</span> (mélange non corrigé)</li></ul>"},{"id":"q-tca-tp","kind":"decision","label":"Plaquettes, fibrinogène et facteur V ? — Le facteur V est le discriminant clé : normal dans l'hypovitaminose K, abaissé dans l'IHC","branches":[{"to":"t-civd","label":"Plaquettes ↓ · fibrinogène ↓ · D-dimères ↑","color":"red"},{"to":"t-ihc","label":"Facteur V abaissé","color":"amber"},{"to":"t-hypovitk","label":"Facteur V normal · fibrinogène normal","color":"amber"}]},{"id":"t-civd","kind":"terminal","label":"CIVD","color":"red","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-bio\">Thrombopénie</span> + <span class=\"kw-bio\">hypofibrinogénémie</span> (précoces) ; <span class=\"kw-bio\">D-dimères &gt; 500 µg/L</span> ; <span class=\"kw-bio\">complexes solubles</span> et <span class=\"kw-bio\">test à l'éthanol</span> positifs ; baisse des facteurs dont le <span class=\"kw-bio\">F8</span></li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Sepsis</span> (1re cause, surtout Gram −) ; <span class=\"kw-def\">choc septique</span>, <span class=\"kw-def\">purpura fulminans</span></li><li>Obstétricales : <span class=\"kw-etio\">hématome rétroplacentaire</span>, embolie amniotique, mort fœtale in utero</li><li>Cancers métastasés, <span class=\"kw-etio\">LAM3</span>, lyse cellulaire (polytraumatisme, brûlures)</li></ul><h4>Gravité</h4><ul><li><span class=\"kw-def\">Score</span> ISTH <span class=\"kw-chiffre\">≥ 5</span> = <span class=\"kw-alerte\">CIVD</span> <span class=\"kw-alerte\">décompensée</span> ; <span class=\"kw-alerte\">défaillance multiviscérale</span></li></ul><h4>PEC</h4><ul><li>Traitement <span class=\"kw-ttt\">étiologique</span> ++ ; <span class=\"kw-ttt\">CPA</span> si <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-chiffre\">&lt; 50 G/L</span> et saignement/acte invasif, <span class=\"kw-ttt\">PFC</span> si <span class=\"kw-bio\">TP</span> <span class=\"kw-chiffre\">&lt; 40 %</span> ; <span class=\"kw-ci\">complexe prothrombinique contre-indiqué</span></li></ul><h4>Renvoi</h4><ul><li>Item 226 (TVP - EP) · Item 329 (transfusion sanguine)</li></ul>"},{"id":"t-ihc","kind":"terminal","label":"Insuffisance hépatocellulaire","color":"amber","detail":"<h4>Confirmation</h4><ul><li>Baisse des facteurs vitamine K-dépendants ET du <span class=\"kw-bio\">FV</span> ; <span class=\"kw-bio\">F8 normal</span> (contrairement à la <span class=\"kw-alerte\">CIVD</span>) ; ± <span class=\"kw-bio\">hypofibrinogénémie</span> et thrombopénie (hypersplénisme)</li></ul><h4>Discriminant</h4><ul><li>Le <span class=\"kw-bio\">facteur V abaissé</span> est le <span class=\"kw-alerte\">signe de gravité</span> qui sépare l'<span class=\"kw-bio\">IHC</span> de l'hypovitaminose K</li></ul><h4>Étiologie</h4><ul><li>Hépatopathie aiguë ou chronique</li></ul>"},{"id":"t-hypovitk","kind":"terminal","label":"Hypovitaminose K (avancée)","color":"amber","detail":"<h4>Confirmation</h4><ul><li>Baisse de <span class=\"kw-bio\">F2, F7, F9, F10</span> ; <span class=\"kw-bio\">FV normal</span> ; <span class=\"kw-bio\">fibrinogène</span> et <span class=\"kw-bio\">plaquettes</span> normaux</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-ttt\">AVK</span> ; <span class=\"kw-ttt\">antibiotiques</span> (destruction de la flore intestinale)</li><li><span class=\"kw-etio\">Carence d'apport</span> (dénutrition sévère, nutrition parentérale exclusive)</li><li><span class=\"kw-etio\">Malabsorption / cholestase</span> (vitamine liposoluble)</li></ul><h4>PEC</h4><ul><li><span class=\"kw-ttt\">Vitamine K1</span> per os ou IV lente (correction en <span class=\"kw-chiffre\">6–12 h</span>) ; <span class=\"kw-ttt\">PPSB</span> si hémorragie grave (effet en <span class=\"kw-chiffre\">30 min</span>)</li></ul>"}]},"cards":[{"i":"6cc7982b563c","n":216,"o":"216-1","u":"Définition","t":"Connaître la définition du syndrome hémorragique d’origine hématologique","q":"Quelle est la définition du syndrome hémorragique d'origine hématologique ?","a":"<p>Le syndrome hémorragique d'origine hématologique correspond à un ensemble de <strong>manifestations hémorragiques anormales</strong> (saignements spontanés, disproportionnés à un traumatisme minime, ou retardés) qui traduisent une <strong>anomalie constitutionnelle ou acquise de l'hémostase</strong>.</p>"},{"i":"9f667104b275","n":216,"o":"216-1","u":"Définition","t":"Connaître la définition du syndrome hémorragique d’origine hématologique","q":"Comment le type d'hémorragie peut-il orienter vers le mécanisme physiopathologique dans le cadre d'un syndrome hémorragique d'origine hématologique ?","a":"<ul><li>Une <strong>hémorragie cutanéo-muqueuse</strong> (purpura, ecchymoses, gingivorragies, épistaxis), spontanée ou provoquée et précoce, oriente vers un <strong>trouble de l'hémostase primaire</strong>.</li><li>Une <strong>hémorragie interne</strong> (hématome, hémarthrose), provoquée par un traumatisme minime et retardée, oriente vers un <strong>trouble de la coagulation</strong> (hémostase secondaire).</li></ul>"},{"i":"d017961a0ea9","n":216,"o":"216-1","u":"Définition","t":"Connaître la définition du syndrome hémorragique d’origine hématologique","q":"Quel piège diagnostique clinique doit-on éviter concernant le purpura dans le cadre d'un syndrome hémorragique d'origine hématologique ?","a":"<p>Il ne faut pas confondre le syndrome hémorragique d'origine hématologique avec le <strong>purpura vasculaire</strong>, qui est dû à une <strong>anomalie de la paroi vasculaire</strong>. Le purpura vasculaire est typiquement <strong>infiltré et palpable</strong> et n'est pas d'origine hématologique.</p>"},{"i":"e2dbe69d66c8","n":216,"o":"216-1","u":"Définition","t":"Connaître la définition du syndrome hémorragique d’origine hématologique","q":"Quelles sont les trois étapes principales de l'hémostase et quel est leur rôle ?","a":"<p>L'hémostase maintient le sang fluide dans les vaisseaux et comporte trois étapes :</p><ul><li>L'<strong>hémostase primaire</strong>.</li><li>La <strong>coagulation</strong> (ou hémostase secondaire).</li><li>La <strong>fibrinolyse</strong>.</li></ul><p>Un défaut à n'importe laquelle de ces étapes peut entraîner un syndrome hémorragique.</p>"},{"i":"06105b9b168a","n":216,"o":"216-3","u":"Diagnostic positif","t":"Connaître les données d’interrogatoire et d’examen orientant vers le diagnostic du syndrome hémorragique et de sa cause","q":"Quelles classes de médicaments faut-il systématiquement interroger devant un syndrome hémorragique ?","a":"<p>Il faut systématiquement interroger sur la prise de :</p><ul><li><strong>Antiplaquettaires</strong></li><li><strong>Anticoagulants</strong> (AVK, AOD, héparines)</li><li><strong>AINS</strong> (Anti-inflammatoires non stéroïdiens)</li><li><strong>ISRS</strong> (Inhibiteurs Sélectifs de la Recapture de la Sérotonine)</li></ul>"},{"i":"098e8a6d0851","n":216,"o":"216-3","u":"Diagnostic positif","t":"Connaître les données d’interrogatoire et d’examen orientant vers le diagnostic du syndrome hémorragique et de sa cause","q":"Comment différencier un purpura thrombopénique d'un purpura vasculaire à l'examen clinique ?","a":"<p>À l'examen clinique :</p><ul><li>Le <strong>purpura thrombopénique</strong> est typiquement <strong>plan</strong> et <strong>non infiltré</strong>.</li><li>Le <strong>purpura vasculaire</strong> est <strong>infiltré</strong> et <strong>palpable</strong>.</li></ul>"},{"i":"4ee46512c3ce","n":216,"o":"216-3","u":"Diagnostic positif","t":"Connaître les données d’interrogatoire et d’examen orientant vers le diagnostic du syndrome hémorragique et de sa cause","q":"Quels antécédents familiaux faut-il rechercher lors de l'interrogatoire d'un patient présentant un syndrome hémorragique, et à quelles causes orientent-ils ?","a":"<p>Il faut rechercher des <strong>antécédents familiaux de saignement</strong>, qui peuvent orienter vers des causes constitutionnelles :</p><ul><li>L'<strong>hémophilie</strong> : transmission liée à l'X, atteint surtout les garçons.</li><li>La <strong>maladie de Willebrand</strong> : autosomique dominante, atteint les deux sexes.</li></ul>"},{"i":"638f855aa24b","n":216,"o":"216-3","u":"Diagnostic positif","t":"Connaître les données d’interrogatoire et d’examen orientant vers le diagnostic du syndrome hémorragique et de sa cause","q":"Quels antécédents personnels hémorragiques sont pertinents à rechercher lors de l'interrogatoire d'un patient et à quelle temporalité de saignement orientent-ils ?","a":"<p>Il est pertinent de rechercher des <strong>saignements prolongés</strong> après une extraction dentaire, une chirurgie ou un accouchement (hémorragie de la délivrance). Les <strong>ménorragies</strong> depuis la puberté et les <strong>épistaxis répétées</strong> sont également des antécédents importants, suggérant souvent un trouble de l'hémostase <strong>primaire ou de la coagulation</strong>.</p>"},{"i":"7b39ddbd66f8","n":216,"o":"216-3","u":"Diagnostic positif","t":"Connaître les données d’interrogatoire et d’examen orientant vers le diagnostic du syndrome hémorragique et de sa cause","q":"Quelles sont les caractéristiques des hémorragies cutanéo-muqueuses et vers quels troubles de l'hémostase orientent-elles ?","a":"<p>Les hémorragies cutanéo-muqueuses (<strong>purpura, ecchymoses, gingivorragies, épistaxis, ménorragies</strong>) ont les caractéristiques suivantes :</p><ul><li>Sont <strong>spontanées</strong> et/ou <strong>provoquées</strong>.</li><li>Apparaissent <strong>précocement</strong> après un traumatisme.</li></ul><p>Elles orientent le plus souvent vers un trouble de l'<strong>hémostase primaire</strong>, comme une <strong>thrombopénie</strong>, une <strong>thrombopathie</strong>, une <strong>maladie de Willebrand</strong> ou une <strong>anomalie vasculaire</strong>.</p>"},{"i":"897befa388b3","n":216,"o":"216-3","u":"Diagnostic positif","t":"Connaître les données d’interrogatoire et d’examen orientant vers le diagnostic du syndrome hémorragique et de sa cause","q":"Que doit-on rechercher à l'examen clinique évoquant une maladie de Rendu-Osler en cas de syndrome hémorragique ?","a":"<p>Il faut rechercher des <strong>télangiectasies</strong>, notamment au niveau du <strong>nez, des lèvres et des doigts</strong>, qui sont évocatrices d'une maladie de Rendu-Osler.</p>"},{"i":"c46891b877e4","n":216,"o":"216-3","u":"Diagnostic positif","t":"Connaître les données d’interrogatoire et d’examen orientant vers le diagnostic du syndrome hémorragique et de sa cause","q":"Quelles caractéristiques du saignement doit-on préciser lors de l'interrogatoire pour orienter l'enquête étiologique d'un syndrome hémorragique ?","a":"<p>Il est essentiel de préciser si le saignement est :</p><ul><li><strong>Spontané</strong> versus <strong>provoqué</strong></li><li><strong>Précoce</strong> versus <strong>retardé</strong></li><li>De type <strong>cutanéo-muqueux</strong> versus <strong>profond</strong></li></ul>"},{"i":"e720753ef542","n":216,"o":"216-3","u":"Diagnostic positif","t":"Connaître les données d’interrogatoire et d’examen orientant vers le diagnostic du syndrome hémorragique et de sa cause","q":"Quelles sont les caractéristiques des hémorragies profondes et vers quels troubles de l'hémostase orientent-elles ?","a":"<p>Les hémorragies profondes (<strong>hématome, hémarthrose</strong>) se caractérisent par :</p><ul><li>Leur survenue <strong>provoquée</strong> par un traumatisme minime.</li><li>Leur apparition <strong>retardée</strong> après le traumatisme.</li></ul><p>Elles orientent vers un trouble de la <strong>coagulation</strong>, comme l'<strong>hémophilie</strong> ou un <strong>déficit en facteur de coagulation</strong>.</p>"},{"i":"0f94c56074fe","n":216,"o":"216-4","u":"Examens complémentaires","t":"Connaître les modalités de prescription des explorations biologiques devant une suspicion de syndrome hémorragique","q":"Quand est-il pertinent de réaliser un Temps de thrombine et qu'explore-t-il ?","a":"<p>Un Temps de thrombine est réalisé en seconde intention lorsqu'on suspecte une anomalie du <strong>fibrinogène</strong> ou la présence d'une <strong>antithrombine</strong> (comme l'héparine ou le dabigatran).</p>"},{"i":"7c9b0f02fc9e","n":216,"o":"216-4","u":"Examens complémentaires","t":"Connaître les modalités de prescription des explorations biologiques devant une suspicion de syndrome hémorragique","q":"Quelles sont les modalités pré-analytiques essentielles pour un bilan d'hémostase fiable ?","a":"<p>Les modalités pré-analytiques essentielles pour assurer la fiabilité d'un bilan d'hémostase sont :</p>\n<ul>\n<li>Un <strong>prélèvement veineux</strong>.</li>\n<li>Sur <strong>tube citraté</strong> (le citrate étant un chélateur du Ca²⁺).</li>\n<li>Le tube doit être <strong>correctement rempli</strong> pour respecter le rapport sang/anticoagulant.<br></li>\n</ul>"},{"i":"8879247486a7","n":216,"o":"216-4","u":"Examens complémentaires","t":"Connaître les modalités de prescription des explorations biologiques devant une suspicion de syndrome hémorragique","q":"Quel est le principe de l'épreuve de mélange et que permet-elle de différencier ?","a":"<p>Le principe de l'épreuve de mélange consiste à mélanger le plasma du patient avec du plasma témoin normale. Elle permet de différencier :</p>\n<ul>\n<li>Une <strong>correction</strong> du temps de coagulation, qui indique un <strong>déficit en facteur</strong> de coagulation.</li>\n<li>Une <strong>absence de correction</strong>, qui suggère la présence d'un <strong>anticoagulant circulant</strong>.</li>\n</ul>"},{"i":"9a295825f302","n":216,"o":"216-4","u":"Examens complémentaires","t":"Connaître les modalités de prescription des explorations biologiques devant une suspicion de syndrome hémorragique","q":"Quels sont les quatre examens biologiques systématiquement inclus dans le bilan d'hémostase de première intention devant une suspicion de syndrome hémorragique ?","a":"<p>Devant une suspicion de syndrome hémorragique, le bilan d'hémostase de première intention inclut systématiquement quatre examens :</p>\n<ul>\n<li><strong>NFS-plaquettes</strong> (la numération plaquettaire est essentielle).</li>\n<li><strong>TP</strong> (ou Taux de Prothrombine), qui explore la voie extrinsèque et la voie commune.</li>\n<li><strong>TCA</strong> (Temps de Céphaline Activée), qui explore la voie intrinsèque et la voie commune.</li>\n<li><strong>Fibrinogène</strong>.</li>\n</ul>"},{"i":"b6ad33ff4216","n":216,"o":"216-4","u":"Examens complémentaires","t":"Connaître les modalités de prescription des explorations biologiques devant une suspicion de syndrome hémorragique","q":"Quelle exploration de l'hémostase est associée au bilan de première intention en fonction du contexte clinique ?","a":"<p>Selon le contexte clinique, un <strong>temps de saignement</strong> ou un <strong>temps d'occlusion plaquettaire (PFA-100)</strong> est associé au bilan de première intention pour explorer l'hémostase primaire.</p>"},{"i":"ca712b58bfa1","n":216,"o":"216-4","u":"Examens complémentaires","t":"Connaître les modalités de prescription des explorations biologiques devant une suspicion de syndrome hémorragique","q":"Comment l'orientation diagnostique est-elle guidée par l'analyse des résultats du Temps de Saignement (TS), du Temps de Céphaline Activée (TCA) et du Taux de Prothrombine (TP) ?","a":"<p>L'orientation diagnostique est guidée par l'analyse des résultats du TS, du TCA et du TP comme suit :</p>\n<ul>\n<li>TS allongé, TCA normal, TP normal : oriente vers une <strong>thrombopénie</strong>, une <strong>thrombopathie</strong>, une anémie ou une anomalie de la paroi vasculaire.</li>\n<li>TS normal, TCA allongé, TP normal : suggère un <strong>anticoagulant circulant (ACC)</strong> ou un déficit/anticorps anti-facteur de la voie intrinsèque (FVIII, FIX, FXI, FXII).</li>\n<li>TS normal, TCA normal, TP allongé : peut indiquer un déficit ou des anticorps anti-FVII, une <strong>insuffisance hépatique sévère (IHC) modérée</strong> ou une carence en vitamine K débutante.</li>\n<li>TS allongé, TCA allongé, TP allongé : évoque une <strong>CIVD</strong>, une fibrinolyse, une afibrinogénémie ou une hypo/dysfibrinogénémie.</li>\n<li>TS normal, TCA allongé, TP allongé : pointe vers un déficit en facteur de la voie commune (FII, FV, FX), une hypo/dysfibrinogénémie ou un syndrome inflammatoire majeur.</li>\n<li>TS allongé, TCA allongé, TP normal : est évocateur de la <strong>maladie de Willebrand</strong>.</li>\n</ul>"},{"i":"11cfb1cc8971","n":216,"o":"216-5","u":"Examens complémentaires","t":"Savoir demander un contrôle de la numération plaquettaire sur citrate devant une thrombopénie sans syndrome hémorragique","q":"Comment confirmer ou infirmer une fausse thrombopénie à l'EDTA ?","a":"<p>Pour confirmer ou infirmer une fausse thrombopénie, il faut :</p><ul><li>Demander un <strong>contrôle de la numération plaquettaire sur tube citraté</strong>.</li><li>Vérifier le <strong>frottis sanguin</strong> : la présence d'<strong>amas plaquettaires</strong> est caractéristique de la pseudo-thrombopénie.</li></ul><p>Si la thrombopénie persiste sur citrate, il s'agit alors d'une vraie thrombopénie nécessitant un bilan étiologique.</p>"},{"i":"5c06c92360b6","n":216,"o":"216-5","u":"Examens complémentaires","t":"Savoir demander un contrôle de la numération plaquettaire sur citrate devant une thrombopénie sans syndrome hémorragique","q":"Quelle est la conduite à tenir essentielle devant une thrombopénie isolée sans syndrome hémorragique ?","a":"<p>La conduite essentielle est de <strong>ne jamais transfuser ni explorer lourdement</strong> une thrombopénie isolée avant d'avoir <strong>éliminé une fausse thrombopénie à l'EDTA</strong> par un contrôle sur tube citraté.</p>"},{"i":"db869da9debd","n":216,"o":"216-5","u":"Examens complémentaires","t":"Savoir demander un contrôle de la numération plaquettaire sur citrate devant une thrombopénie sans syndrome hémorragique","q":"Quel est le contexte clinique évocateur d'une fausse thrombopénie à l'EDTA ?","a":"<p>Une fausse thrombopénie doit être évoquée en priorité lorsqu'une <strong>thrombopénie isolée</strong> est découverte chez un patient <strong>sans aucun syndrome hémorragique</strong>.</p>"},{"i":"fff3a6a966a2","n":216,"o":"216-5","u":"Examens complémentaires","t":"Savoir demander un contrôle de la numération plaquettaire sur citrate devant une thrombopénie sans syndrome hémorragique","q":"Quelle est l'origine du piège diagnostique de la fausse thrombopénie à l'EDTA ?","a":"<p>La fausse thrombopénie est due à l'<strong>agglutination des plaquettes <em>in vitro</em></strong> en présence d'<strong>EDTA</strong> chez environ 1% de la population. Le compteur automatisé interprète ces agrégats comme des cellules uniques, entraînant une <strong>sous-estimation du nombre de plaquettes</strong>.</p>"},{"i":"18349c56c639","n":216,"o":"216-6","u":"Identifier une urgence","t":"Identifier les valeurs de plaquettes, TCA, TP, fibrinogène associées à un risque d’hémorragie spontanée","q":"Quelle association de perturbations du bilan d'hémostase doit faire évoquer une CIVD décompensée, selon l'objectif du syndrome hémorragique d'origine hématologique ?","a":"<p>L'association d'une <strong>thrombopénie profonde</strong>, d'une <strong>chute du fibrinogène</strong>, et d'un <strong>allongement du TCA et du TP</strong> doit faire évoquer une CIVD décompensée. Il s'agit d'une situation d'urgence.</p>"},{"i":"60799df75ae6","n":216,"o":"216-6","u":"Identifier une urgence","t":"Identifier les valeurs de plaquettes, TCA, TP, fibrinogène associées à un risque d’hémorragie spontanée","q":"Que signifie un allongement franc du TCA dans le contexte d'un syndrome hémorragique d'origine hématologique ?","a":"<p>Un allongement franc du TCA traduit un <strong>déficit profond en facteur de la coagulation</strong> et doit faire l'objet d'une exploration urgente.</p>"},{"i":"a1601fd72e56","n":216,"o":"216-6","u":"Identifier une urgence","t":"Identifier les valeurs de plaquettes, TCA, TP, fibrinogène associées à un risque d’hémorragie spontanée","q":"Quelle valeur de fibrinogène est associée à un risque hémorragique majeur, selon l'objectif du syndrome hémorragique d'origine hématologique ?","a":"<p>Un fibrinogène inférieur à <strong>1 g/L</strong> est associé à un risque hémorragique majeur.</p>"},{"i":"cbe444c2bfd2","n":216,"o":"216-6","u":"Identifier une urgence","t":"Identifier les valeurs de plaquettes, TCA, TP, fibrinogène associées à un risque d’hémorragie spontanée","q":"Quelle valeur du Taux de Prothrombine (TP) est associée à un risque hémorragique majeur, selon l'objectif du syndrome hémorragique d'origine hématologique ?","a":"<p>Un TP inférieur à <strong>30%</strong> est associé à un risque hémorragique majeur.</p>"},{"i":"eedd6810badd","n":216,"o":"216-6","u":"Identifier une urgence","t":"Identifier les valeurs de plaquettes, TCA, TP, fibrinogène associées à un risque d’hémorragie spontanée","q":"Quelle valeur de thrombopénie est associée à un risque majeur d'hémorragie spontanée, selon l'objectif du syndrome hémorragique d'origine hématologique ?","a":"<p>Une thrombopénie inférieure à <strong>20 G/L</strong> est associée à un risque majeur d'hémorragie spontanée, notamment rétinienne ou méningée.</p>"}]};